// NowPlaying.js

import React from 'react';
import './NowPlaying.css';

function NowPlaying({ name, idSrc }) {
    const mp3Ref = "https://drive.google.com/file/d/" + idSrc + "/preview";
    const dwnRef = "https://drive.google.com/uc?export=download&id=" + idSrc;

    return (
        <div className='nowPlaying'>
            <p className='currTitle'>Now Playing: <a href={dwnRef}>{name}</a></p>

            <iframe src={mp3Ref} className='currMp3' title='archiveFile'/>
        </div>
    );
};

export default NowPlaying;